#!/usr/bin/env node
// World-scope conformance runner (see DESIGN.md): the rules that audit repo
// state as it exists now, plus the pack-agnostic settings/load integrity
// diagnostics (malformed config, an unknown pack, a broken pack.mjs). Rules that
// judge the current change (`scope: 'work'`) run in check_the_work.mjs, which
// this file shares no code with — only the scope-blind mechanism helpers
// (run-active-pack-rules.mjs, report-findings.mjs). It names NO pack: adoption
// interview hygiene is a skill-owned check that rides its own pack's activation,
// and a malformed `questions` field is a load fault the pack registry reports.
// Wired into the project's test/CI flow, not the Stop hook. Dependency-free Node ≥18.
//   (default)   whole-repo sweep — milliseconds on a text corpus, sees cross-file breakage
//   --changed   transitional: scope to files changed vs the merge-base with main
//               (adopting a repo with a backlog only — not the enforcement default)
//   --base REF  override the base ref
//   --list      machine-readable catalog of every rule, both scopes (id, severity, description, doc)
//   --init      write .claudinite-checks.json — basics plus the fingerprinted packs
import { writeFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { buildContext } from './helpers/repo-context.mjs';
import { discoverPacks, resolveDeclaredPacks } from '../pack_loader/pack-registry.mjs';
import { runActivePackRules, packRules } from './run-active-pack-rules.mjs';
import { reportFindings } from './report-findings.mjs';

const configError = (what, fix) => ({
  rule: 'config', severity: 'blocking', file: '.claudinite-checks.json', line: null,
  what, why: 'the settings file is what executes — a bad key, value, or pack name silently changes what runs', fix, doc: 'engine/checks/README.md',
});

const args = process.argv.slice(2);
const has = (flag) => args.includes(flag);
const value = (flag) => (args.includes(flag) ? args[args.indexOf(flag) + 1] : null);
const root = value('--root') || process.cwd();

if (has('--list')) {
  const { packs } = await discoverPacks({ localRoot: root });
  for (const r of packRules(packs)) {
    console.log(`${r.id}\t${r.severity}\t${r.description}\t${r.doc}`);
  }
  process.exit(0);
}

if (has('--init')) {
  const path = join(root, '.claudinite-checks.json');
  if (existsSync(path)) {
    console.log(`${path} already exists — leaving it as-is.`);
    process.exit(0);
  }
  const { packs } = await discoverPacks({ localRoot: root });
  const ctx = buildContext({ root, mode: 'all' });
  // No pack is active by default, so the baseline is seeded as an explicit
  // declaration alongside the fingerprinted packs: every pack that flags
  // `seededByDefault` is written in (discovered structurally — the engine names
  // no pack), plus the ones a fingerprint detects. A seeded pack is still
  // opt-out-able where its own policy allows (baselining re-adds only the packs
  // whose absence it treats as drift), so removing a seeded declaration can
  // stick; each seeded pack ships its own one-time seed migration for the fleet.
  // Local packs are declared by hand, never fingerprinted or seeded — exclude
  // them from --init's seeding so a repo that already carries local packs (but
  // no config yet) doesn't auto-declare them.
  const seeded = packs.filter((p) => p.seededByDefault && !p.local).map((p) => p.id);
  const detected = [...seeded, ...packs.filter((p) => p.detect && !p.local && p.detect(ctx)).map((p) => p.id)];
  // A pack can't be imported without its dependencies — pull each declared pack's
  // `requires` closure into the declaration so it's complete and visible.
  const declared = resolveDeclaredPacks(detected, packs);
  // maintenance.delivery is deliberately materialized, not defaulted — the selection
  // must be visible in the file where a project would change it (see engine/checks/README.md).
  // Only what carries a decision: the declaration and the always-explicit
  // delivery. Empty rules/accept boilerplate is noise, not settings (#385);
  // loadConfig defaults absent keys.
  writeFileSync(path, `${JSON.stringify({ packs: declared, maintenance: { delivery: 'auto-merge' } }, null, 2)}\n`);
  console.log(`Wrote ${path} (packs: ${declared.join(', ')}).`);
  // The adoption interview (surfacing each declared pack's pending questions) is
  // driven by the adopt-claudinite skill / bootstrap.md, and nudged every session
  // by the SessionStart interview-check step — not printed here, so this runner
  // imports no pack.
  process.exit(0);
}

const { packs, errors: packErrors } = await discoverPacks({ localRoot: root });
const ctx = buildContext({ root, mode: has('--changed') ? 'changed' : 'all', baseOverride: value('--base') });

1	// Shared plumbing for this pack's checks.
2	//
3	// Deliberately dependency-free: a local pack's check modules must load even when
4	// the gitignored canon mount is absent (the project's own vitest run is exactly
5	// that situation), so nothing here imports `engine/checks/helpers/*`. The two
6	// things every rule needs are a finding constructor and a comment stripper.
7	
8	/** The plain finding object the checks runner consumes (engine/checks/README.md). */
9	export function finding(rule, { file, line = null, what, fix, why = null, severity = null }) {
10	  return {
11	    rule: rule.id,
12	    severity: severity || rule.severity,
13	    file,
14	    line,
15	    what,
16	    why: why || rule.why,
17	    fix,
18	    doc: rule.doc,
19	  };
20	}
21	
22	// String-aware comment stripper. Every rule below matches against source *code*:
23	// a comment that merely names `chrome.tts.speak` or `getUserMedia` describes the
24	// trap, it doesn't spring it — and this pack's own prose would otherwise fire its
25	// own checks. Same technique the repo's arch test already uses
26	// (extension-test/unit/arch.test.js), kept here so the pack stands alone.
27	// Newlines are preserved so line numbers survive the strip.
28	export function stripComments(source) {
29	  let out = '';
30	  let state = 'code'; // code | line | block | sq | dq | tpl
31	  for (let i = 0; i < source.length; i++) {
32	    const c = source[i];
33	    const c2 = source[i + 1];
34	    if (state === 'code') {
35	      if (c === '/' && c2 === '/') { state = 'line'; i++; continue; }
36	      if (c === '/' && c2 === '*') { state = 'block'; i++; continue; }
37	      if (c === "'") state = 'sq';
38	      else if (c === '"') state = 'dq';
39	      else if (c === '`') state = 'tpl';
40	      out += c;
41	    } else if (state === 'line') {
42	      if (c === '\n') { state = 'code'; out += c; }
43	    } else if (state === 'block') {
44	      if (c === '*' && c2 === '/') { state = 'code'; i++; }
45	      else if (c === '\n') out += c;
46	    } else {
47	      out += c;
48	      if (c === '\\') { out += c2 ?? ''; i++; }
49	      else if ((state === 'sq' && c === "'") || (state === 'dq' && c === '"') || (state === 'tpl' && c === '`')) {
50	        state = 'code';
51	      }
52	    }
53	  }
54	  return out;
55	}
56	
57	// What counts as shipped browser source. Deliberately NOT a hard-coded project
58	// root: every rule in this pack is gated on the speech API it judges actually
59	// appearing in the file, so the trigger is the API usage itself and the scan can
60	// safely be repo-shaped. A path scope hard-wired to one project's layout would
61	// make all three rules match zero files — and pass VACUOUSLY GREEN — in any repo
62	// laid out differently, which is the worst failure mode a check has.
63	//
64	// The one thing the scan must still exclude is test scaffolding: hand-rolled
65	// speech fakes implement only the halves of a contract a given case exercises,
66	// and holding purpose-built scaffolding to the production contract is a false
67	// alarm. That exclusion is expressed directly — by test/vendor path and test
68	// filename — instead of being a side effect of the source root.
69	const SOURCE_EXT = /\.(?:m|c)?[jt]sx?$/;
70	const NOT_SOURCE = [
71	  /(?:^|\/)(?:node_modules|dist|build|out|coverage|vendor|third_party)\//,
72	  /(?:^|\/)(?:tests?|__tests__|__mocks__|spec|fixtures?|mocks?|e2e)\//,
73	  /(?:^|[./-])(?:test|spec|fixture|mock|stub|fake)s?\.[^/]+$/,
74	];
75	export const isSource = (file) => SOURCE_EXT.test(file) && !NOT_SOURCE.some((re) => re.test(file));
76	
77	/** 1-based line number of `index` in `text`. */
78	export const lineOf = (text, index) => text.slice(0, index).split('\n').length;
79	
80	/**
81	 * Both legal ways to wire a speech event, as one matcher: the `onfoo =` property
82	 * assignment and `addEventListener('foo', …)`. The DOM offers both for every one
83	 * of these targets and neither is more correct, so a rule that knows only the
84	 * property form silently passes half the world's code — and false-alarms on a
85	 * file that mixes the two (`rec.onresult = …` beside
86	 * `rec.addEventListener('error', …)` reads as "no error handler" to a matcher
87	 * that only understands `.onerror =`).
88	 */
89	export const wires = (src, event) =>
90	  new RegExp(
91	    `\\.\\s*on${event}\\s*=|addEventListener\\s*\\(\\s*['"\`]${event}['"\`]`,
92	  ).test(src);
93	
94	/** Does `text` contain `name` as a string literal? */
95	export const quoted = (text, name) => new RegExp(`['"\`]${name}['"\`]`).test(text);
96	
97	/**
98	 * The balanced bracketed run beginning at the opener at `open` (inclusive of both
99	 * brackets), or null when the source is unbalanced — a half-written file should
100	 * make a check say nothing, never guess. String and template literals are skipped
101	 * so a bracket inside "a(b)" can't be read as syntax.
102	 */
103	export function balanced(src, open) {
104	  let depth = 0;
105	  for (let i = open; i < src.length; i++) {
106	    const c = src[i];
107	    if (c === '"' || c === "'" || c === '`') {
108	      const quote = c;
109	      for (i += 1; i < src.length; i++) {
110	        if (src[i] === '\\') { i += 1; continue; }
111	        if (src[i] === quote) break;
112	      }
113	      continue;
114	    }
115	    if (c === '{' || c === '[' || c === '(') depth += 1;
116	    else if (c === '}' || c === ']' || c === ')') {
117	      depth -= 1;
118	      if (depth === 0) return src.slice(open, i + 1);
119	    }
120	  }
121	  return null;
122	}
123

1	import { finding, stripComments, isSource, lineOf } from './lib.mjs';
2	
3	// A getUserMedia stream is only released when its TRACKS are stopped. Dropping
4	// the reference, closing an AudioContext, unsetting a srcObject, or letting the
5	// function return does not free the device: the browser's recording indicator
6	// and the OS microphone indicator both stay lit, and on some platforms the
7	// device stays claimed until the tab closes. On anything voice-driven that is
8	// the most alarming possible bug — the app looks like it is listening to the
9	// user when it isn't.
10	//
11	// The release belongs in a `finally`, so that no early return, rejection, or
12	// throw between opening the capture and finishing with it can leave the device
13	// held — a permission preflight that opens a stream just to learn whether it is
14	// allowed is the classic instance, since everything it does in between can throw.
15	//
16	// Deliberately file-scoped rather than flow-scoped: proving a particular stream
17	// is stopped needs real data-flow analysis, and a check that guesses is worse
18	// than one that asks a simple, honest question — "this file opens a capture;
19	// does it anywhere stop the tracks?". A property reference
20	// (`if (!media?.getUserMedia)`) is not a call and does not trigger it; comments
21	// are stripped first.
22	
23	const CALL = /\bgetUserMedia\s*\(/g;
24	const RELEASE = /\bgetTracks\b|\bgetAudioTracks\b/;
25	const STOP = /\.\s*stop\s*\(/;
26	
27	const rule = {
28	  id: 'mic-capture-released',
29	  severity: 'blocking',
30	  description: 'A file that opens a getUserMedia capture also stops its tracks',
31	  doc: '.claudinite/local/packs/browser-speech/RULES.md',
32	  why: 'a media stream is freed only by stopping its tracks — dropping the reference leaves the browser and OS microphone indicators lit and the device claimed, which on anything voice-driven reads to the user as "it is still listening to me"',
33	
34	  run(ctx) {
35	    const out = [];
36	    for (const file of ctx.files) {
37	      if (!isSource(file)) continue;
38	      const raw = ctx.read(file);
39	      if (raw === null || !raw.includes('getUserMedia')) continue;
40	      const src = stripComments(raw);
41	      CALL.lastIndex = 0;
42	      const first = CALL.exec(src);
43	      if (!first) continue;
44	      if (RELEASE.test(src) && STOP.test(src)) continue;
45	      out.push(finding(rule, {
46	        file,
47	        line: lineOf(src, first.index),
48	        what: 'opens a microphone capture but never stops its tracks',
49	        fix: 'release the capture with stream.getTracks().forEach((t) => t.stop()), and put that call in a `finally` so no early return, rejection, or throw from the code in between can leave the device held',
50	      }));
51	    }
52	    return out;
53	  },
54	};
55	
56	export default rule;
57

1	import { finding, stripComments, isSource, lineOf, balanced } from './lib.mjs';
2	
3	// `suppressLocalAudioPlayback` and `restrictOwnAudio` are `getDisplayMedia`
4	// SCREEN-CAPTURE constraints. They filter the playout of a captured tab out of
5	// that tab's audio track; they say nothing about a microphone, and getUserMedia
6	// ignores them entirely — no throw, no warning, no `OverconstrainedError`.
7	//
8	// They are reached for by name: someone hunting the app's own TTS leaking back
9	// through the mic reads "suppress local audio playback" / "restrict own audio"
10	// as exactly the fix, sets it on the mic capture, and ships believing self-echo
11	// is handled at the capture layer. It isn't, and the code that would have
12	// handled it (an application-level echo guard) never gets written. That is the
13	// silent-failure shape this whole pack is about: nothing throws, nothing logs,
14	// the feature simply doesn't exist.
15	//
16	// PARSED, NOT GREPPED. The names are only wrong where they reach a microphone
17	// capture, so the scan is the balanced argument list of a `getUserMedia(` call —
18	// plus, one hop, the initializer of any same-file constant that argument list
19	// references, since hoisting the constraints into a frozen constant is the
20	// ordinary way to write this:
21	//
22	//     const AUDIO = Object.freeze({ echoCancellation: true });
23	//     await media.getUserMedia({ audio: AUDIO });
24	//
25	// Everything outside that reach stays quiet on purpose — a file's real
26	// getDisplayMedia call, a `getSupportedConstraints()` probe, a screen-capture
27	// module's own constants table are all legitimate uses of these names, and a
28	// rule that grepped the file would false-alarm on every one of them. Comments
29	// are stripped first, so the paragraphs above cannot fire the rule.
