63	  let hasDefault = false;
64	  let depth = 0;
65	  for (let i = 1; i < body.length - 1; i++) {
66	    const c = body[i];
67	    if (c === '"' || c === "'" || c === '`') {
68	      const quote = c;
69	      for (i += 1; i < body.length; i++) {
70	        if (body[i] === '\\') { i += 1; continue; }
71	        if (body[i] === quote) break;
72	      }
73	      continue;
74	    }
75	    if (c === '{' || c === '[' || c === '(') { depth += 1; continue; }
